head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > validateRef]<br/>ref 속성으로 바인딩된 DataCollection 에 의해 입력값이 설정될때 유효성을 체크합니다.",
    "validation" : [        
        "validCheck=true, dateValidSet=false 이고 입력값이 있을때 동작합니다.",
        "ref 속성으로 바인딩된 DataCollection 에 의해 입력값이 설정될때 유효성을 체크합니다.",
        "미설정 시 입력값이 바인딩된 DataCollection 에 의해 설정될때 유효성을 체크하지 않습니다.",
        "true 설정 시 입력값이 바인딩된 DataCollection 에 의해 설정될때 유효성을 체크합니다.",
        "true 설정 시 유효하지 않은 입력값을 삭제하고 ''(Empty String)이 설정됩니다.",
        "true 설정 시 유효하지 않은 입력값이 삭제되면 DataCollection 에도 ''(Empty String)이 반영됩니다.",
        "false 미설정 시 입력값이 바인딩된 DataCollection 에 의해 설정될때 유효성을 체크하지 않습니다.",        
    ]
}


scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }

    let properties = {
        ref : "data:dlt_ref.label",
        validCheck : true,
        dateValidSet : false,
        validateRef : con_validateRef.getText(),
    }

    let cList = $c.gcm.createCList(properties);  

    // comp 생성 함수 호출
    let grp_comp = $c.gcm.getTestGroup();
    let strDltRef = '';
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $p.data.remove("dlt_ref");

    strDltRef += '<w2:dataList baseNode="list" repeatNode="map" id="dlt_ref">';
    strDltRef += '<w2:columnInfo>';
    strDltRef += '<w2:column id="label" name="name1" dataType="text"></w2:column>';
    strDltRef += '<w2:column id="value" name="name2" dataType="text"></w2:column>';
    strDltRef += '</w2:columnInfo>';
    strDltRef += '<w2:data use="true">';
    strDltRef += '<w2:row>';
    strDltRef += '<label><![CDATA[20251301]]></label>';
    strDltRef += '<value><![CDATA[1]]></value>';
    strDltRef += '</w2:row>';
    strDltRef += '</w2:data>';
    strDltRef += '</w2:dataList>';

    $p.data.create(strDltRef);

    strTarget += '<w2:inputCalendar ' + strNameSpace + ' ' + cList + ' style="width:150px; height:23px; " calendarValueType="yearMonthDate"></w2:inputCalendar>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "inputCalendar",
        strTarget,
        grp_comp
    );    

    strGridView += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_ref" id="gridView1" style="width: 500px;height: 150px;">';
    strGridView += '<w2:caption id="caption1" style="" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header id="header1" style="">';
    strGridView += '<w2:row id="row1" style="">';
    strGridView += '<w2:column width="140" inputType="text" style="" id="column1" value="name1"></w2:column>';
    strGridView += '<w2:column width="136" inputType="text" style="" id="column3" value="name2" displayMode="label"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody id="gBody1" style="">';
    strGridView += '<w2:row id="row2" style="">';
    strGridView += '<w2:column width="140" inputType="text" style="" id="label" value=""></w2:column>';
    strGridView += '<w2:column width="136" inputType="text" style="" id="value" value="" displayMode="label"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';

    // target 생성
    scwin.gridView1 = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    
}



scwin.btn_getValue_onclick = function (e) {
    let rtn = '';

    rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 확인 : " + rtn);       

    rtn = dlt_ref.getRowData(0);
    wf_body_bottom.getObj("scwin").setReturnValue("DataList 값 확인 : " + rtn);       
};
